mapper.select:
SELECT notice_id AS id, title, content, summary, publisher, publisher_type, publisher_dept, top_flag, status, create_time FROM citizen_notice WHERE status = 1
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY top_flag DESC, create_time DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE citizen_notice
SET title = #{title}, content = #{content}, summary = #{summary}
WHERE notice_id = #{noticeId}
